package com.xauusd.analyzer;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 int bg=Color.rgb(7,13,27),panel=Color.rgb(13,23,43),cyan=Color.rgb(38,211,230),white=Color.rgb(230,239,250),muted=Color.rgb(132,155,183),red=Color.rgb(255,79,95),blue=Color.rgb(55,145,255),green=Color.rgb(52,220,160); LinearLayout root; int page=0;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);showPage();}
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(12);d.setStroke(1,Color.rgb(36,57,83));return d;}
 TextView tx(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(null,1);t.setPadding(8,4,8,4);return t;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} void add(LinearLayout p,View v,int w,int h){p.addView(v,new LinearLayout.LayoutParams(w,h));}
 void card(LinearLayout p,String title,String body,int color){LinearLayout c=col();c.setPadding(8,5,8,5);c.setBackground(shape(panel));add(c,tx(title,12,color,true),-1,-2);add(c,tx(body,10,white,false),-1,-2);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(3,3,3,3);p.addView(c,lp);}
 void showPage(){root=col();root.setPadding(8,4,8,4);root.setBackgroundColor(bg);setContentView(root);LinearLayout head=row();TextView title=tx("XAUUSD ANALYZER",20,cyan,true);head.addView(title,new LinearLayout.LayoutParams(0,42,1));add(head,tx("XAUUSD • DEMO UI • LIVE DATA NOT CONNECTED",10,muted,true),-2,42);add(root,head,-1,42);
 if(page==0){LinearLayout tf=row();String[] a={"M1","M5","M15","M30","H1","H4","H8","H12","D1","W1"};for(int i=0;i<a.length;i++){TextView t=tx(a[i],10,i==2?bg:cyan,true);t.setGravity(17);t.setBackground(shape(i==2?cyan:panel));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,30,1);lp.setMargins(2,2,2,2);tf.addView(t,lp);}add(root,tf,-1,34);LinearLayout chart=col();chart.setBackground(shape(panel));add(chart,tx("PRICE STRUCTURE • MULTI-TIMEFRAME LEVELS",11,white,true),-1,25);chart.addView(new CandleView(),new LinearLayout.LayoutParams(-1,0,1));root.addView(chart,new LinearLayout.LayoutParams(-1,0,1));LinearLayout info=row();card(info,"STRUCTURE","HH / HL / LH / LL\nAwaiting candle data",cyan);card(info,"SUPPLY ZONE","Not calculated\nNeeds OHLC data",red);card(info,"DEMAND ZONE","Not calculated\nNeeds OHLC data",blue);add(root,info,-1,75);LinearLayout det=row();card(det,"BREAKOUT","No signal",green);card(det,"RETEST","Waiting",cyan);card(det,"UNBROKEN LEVELS","Pending",blue);card(det,"REVERSAL","No signal",red);add(root,det,-1,66);
 }else{LinearLayout a=row();card(a,"MARKET OVERVIEW","Live price feed not connected",cyan);card(a,"PRIMARY SCENARIO","Not calculated from market data",green);card(a,"ALTERNATIVE SCENARIO","Not calculated from market data",red);add(root,a,-1,100);LinearLayout b=row();card(b,"MARKET JOURNEY","Swing sequence awaits data",cyan);card(b,"NEXT LEVELS","Levels await calculation",blue);card(b,"SUPPORT / INVALIDATION","No trading signal generated",muted);add(root,b,-1,110);}
 LinearLayout foot=row();TextView p1=tx("PAGE 1 • STRUCTURE & ZONES",10,page==0?cyan:muted,true),p2=tx("PAGE 2 • SCENARIOS",10,page==1?cyan:muted,true);p1.setGravity(17);p2.setGravity(17);p1.setOnClickListener(v->{page=0;showPage();});p2.setOnClickListener(v->{page=1;showPage();});foot.addView(p1,new LinearLayout.LayoutParams(0,32,1));foot.addView(p2,new LinearLayout.LayoutParams(0,32,1));add(root,foot,-1,34);}
 class CandleView extends View{Paint p=new Paint(3);CandleView(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(Color.rgb(30,48,71));p.setStrokeWidth(1);for(int i=1;i<6;i++)c.drawLine(0,h*i/6,w,h*i/6,p);for(int i=0;i<24;i++){float x=18+i*(w-36)/24f,y=h*(.55f-(float)Math.sin(i*.62)*.18f);p.setColor(i%3==0?red:green);p.setStrokeWidth(2);c.drawLine(x,y-15,x,y+18,p);c.drawRect(x-4,y-8,x+4,y+9,p);}p.setColor(cyan);p.setTextSize(11);c.drawText("Illustrative chart — live market feed not connected",12,16,p);}}
}
